require(script.Parent.Parent.Parent.Parent.Parent:WaitForChild(".luau-aliases"):WaitForChild("@jsdotlua"):WaitForChild("es7-types"))
return function(list, p, value: number?)
	local v = value or 1
	local count = #list

	if v < 1 then
		v = math.max(count - math.abs(v), 1)
	end

	for i = v, count do
		if list[i] == p then
			return i
		end
	end

	return -1
end